def IsStrictlySingularOperator (T : X →L[𝕜] X) : Prop :=
  ∀ E : Submodule 𝕜 X,
    (∃ c : ℝ, 0 < c ∧ ∀ x : E, c * ‖x‖ ≤ ‖T x.val‖) → FiniteDimensional 𝕜 E

